import os

def read_report(filename: str, reports_root: str) -> str:
    reports_root = os.path.abspath(reports_root)
    requested_path = os.path.join(reports_root, filename)
    requested_path = os.path.abspath(requested_path)

    if not requested_path.startswith(reports_root + os.sep) and requested_path != reports_root:
        raise ValueError("Request disallowed: path traversal detected")

    if not os.path.exists(requested_path):
        raise FileNotFoundError(f"File not found: {requested_path}")

    if not os.path.isfile(requested_path):
        raise ValueError("Request disallowed: not a regular file")

    with open(requested_path, 'r', encoding='utf-8') as f:
        return f.read()
